    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def safe_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def toward(a, b):
        ax, ay = a
        bx, by = b
        return [sign(bx - ax), sign(by - ay)]

    def away(a, b):
        ax, ay = a
        bx, by = b
        return [sign(ax - bx), sign(ay - by)]

    env = observation.get("environment_name", "") or "resource_collection"
    sx, sy = safe_pos(observation.get("self_position"))
